#include <stdio.h>
#include <string.h>
#include <ctype.h>

#define LINE_MAX   2048
#define OUT_MAX    1024

static void url_decode(const char *src, size_t len, char *dst)
{
    size_t i = 0, out = 0;
    while (i < len) {
        char c = src[i];
        if (c == '+') {
            dst[out++] = ' ';
            ++i;
        } else if (c == '%' && i + 2 < len && isxdigit((unsigned char)src[i+1]) && isxdigit((unsigned char)src[i+2])) {
            char hi = src[i+1];
            char lo = src[i+2];
            int vhi = (hi >= '0' && hi <= '9') ? hi - '0' : (hi >= 'A' && hi <= 'F') ? hi - 'A' + 10 : hi - 'a' + 10;
            int vlo = (lo >= '0' && lo <= '9') ? lo - '0' : (lo >= 'A' && lo <= 'F') ? lo - 'A' + 10 : lo - 'a' + 10;
            dst[out++] = (char)((vhi << 4) | vlo);
            i += 3;
        } else {
            dst[out++] = c;
            ++i;
        }
    }
    dst[out] = '\0';
}

int main(void)
{
    static char line[LINE_MAX];
    static char key[OUT_MAX];
    static char val[OUT_MAX];

    if (fgets(line, sizeof(line), stdin) == NULL) {
        puts("NO_INPUT");
        return 0;
    }
    size_t linelen = strlen(line);
    if (linelen && line[linelen-1] == '\n') {
        line[--linelen] = '\0';
        if (linelen && line[linelen-1] == '\r')
            line[--linelen] = '\0';
    }
    const char *p = line;
    while (*p) {
        const char *token_end = strchr(p, '&');
        if (!token_end) token_end = p + strlen(p);
        const char *eq = memchr(p, '=', (size_t)(token_end - p));
        if (eq) url_decode(p, (size_t)(eq - p), key);
        else url_decode(p, (size_t)(token_end - p), key);
        if (eq) url_decode(eq+1, (size_t)(token_end - (eq+1)), val);
        else val[0] = '\0';
        printf("%s=%s\n", key, val);
        if (*token_end == '&') p = token_end + 1; else break;
    }
    return 0;
}
